def _backfill_default_categories():
    """Give users who registered before this migration their default categories.

    Insert-only and idempotent: a category the user already has (same type and
    name, case-insensitive) is left untouched. Skipped in offline --sql mode.
    """
    if context.is_offline_mode():
        return
    bind = op.get_bind()
    users = sa.table('users', sa.column('id', sa.Integer))
    categories = sa.table(
        'categories',
        sa.column('user_id', sa.Integer), sa.column('name', sa.String),
        sa.column('type', sa.String), sa.column('is_default', sa.Boolean),
    )
    for user_id in [row[0] for row in bind.execute(sa.select(users.c.id))]:
        existing = {
            (row[0], row[1].lower())
            for row in bind.execute(
                sa.select(categories.c.type, categories.c.name).where(categories.c.user_id == user_id)
            )
        }
        rows = [
            {'user_id': user_id, 'name': name, 'type': flow, 'is_default': True}
            for flow, names in _DEFAULT_CATEGORIES
            for name in names
            if (flow, name.lower()) not in existing
        ]
        if rows:
            op.bulk_insert(categories, rows)


